import re

# Let's first check for apologies in agent messages
# An apology would be words like "sorry", "apologize", "apologies", "apology" from the company/agent

def has_agent_apology(dialog_text, company_id):
    """Check if the support agent apologizes in the dialog"""
    # Split into messages
    messages = dialog_text.split('\n\n')
    apology_patterns = re.compile(r'\b(sorry|apologize|apologies|apology|apologise)\b', re.IGNORECASE)

    for msg in messages:
        # Check if message is from the company (agent)
        if msg.strip().startswith(company_id):
            if apology_patterns.search(msg):
                return True
    return False

# Let's count apologies per company
apology_stats = {}
for company in companies:
    company_dialogs = [d for d in dataset if d['company_id'] == company]
    apology_count = sum(1 for d in company_dialogs if has_agent_apology(d['dialog'], company))
    apology_stats[company] = {
        'total': len(company_dialogs),
        'with_apology': apology_count,
        'apology_rate': apology_count / len(company_dialogs) if company_dialogs else 0
    }

for company, stats in sorted(apology_stats.items(), key=lambda x: x[1]['apology_rate'], reverse=True):
    print(f"{company}: {stats['with_apology']}/{stats['total']} = {stats['apology_rate']:.2%}")
